import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    # Note: m*ceil(n*alpha) - n*floor(m*alpha) = k
    val = m * math.ceil(n * alpha) - n * math.floor(m * alpha)
    return val == k

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False
    # Neither (m-n, n) nor (m, n-m) are pretty
    if m > n:
        if is_pretty(m - n, n, alpha, k):
            return False
    if n > m:
        if is_pretty(m, n - m, alpha, k):
            return False
    return True

def count_cool_pairs(k, alpha):
    # Range for m, n needs to be carefully considered.
    # For k=1, we saw it's around k.
    # Let's check if count is related to divisors of k.
    limit = k + 2
    count = 0
    for m in range(1, limit):
        for n in range(1, limit):
            if is_cool(m, n, alpha, k):
                count += 1
    return count

# Test with various irrational alphas to see if count is independent of alpha
alphas = [math.sqrt(2), math.sqrt(3), math.e, math.pi]
k_vals = list(range(1, 11))

results = {}
for k in k_vals:
    counts = []
    for a in alphas:
